import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
import { t } from '../utils/settings';
import { categorySymbol, tagSymbol, primaryTags, secondaryTags, sortTags, allTags } from '../utils/tags';
import { getSidebarPicks, setSidebarPicks } from '../utils/sidebarPrefs';
/**
 * "Editar a seção": uma lista com busca e caixas de seleção das
 * categorias (ou etiquetas) que aparecem na barra lateral.
 */
export default class SidebarCustomizeModal extends Modal {
  selected = new Set();
  filter = '';
  oninit(vnode) {
    super.oninit(vnode);
    const picks = getSidebarPicks(this.attrs.section);
    const initial = picks ?? this.defaultTags().map(tag => tag.id());
    this.selected = new Set(initial);
  }
  className() {
    return 'CanelaSidebarCustomize Modal--small';
  }
  title() {
    return t(this.attrs.section === 'categories' ? 'sidebar.customize_categories' : 'sidebar.customize_tags');
  }

  /** O que a seção mostra sem escolha: as primárias, ou as etiquetas mais usadas. */
  defaultTags() {
    return this.attrs.section === 'categories' ? primaryTags() : secondaryTags();
  }
  candidates() {
    const tags = this.attrs.section === 'categories' ? sortTags(allTags().filter(tag => tag.position() !== null)) : secondaryTags();
    const query = this.filter.trim().toLowerCase();
    return query ? tags.filter(tag => tag.name().toLowerCase().includes(query)) : tags;
  }
  content() {
    const candidates = this.candidates();
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      type: "search",
      placeholder: t('sidebar.customize_filter'),
      value: this.filter,
      oninput: event => this.filter = event.target.value
    })), m("ul", {
      className: "CanelaSidebarCustomize-list"
    }, candidates.map(tag => {
      const id = tag.id();
      const checked = this.selected.has(id);
      return m("li", {
        className: classList({
          'CanelaSidebarCustomize-item--child': tag.isChild()
        })
      }, m("label", {
        className: "checkbox"
      }, m("input", {
        type: "checkbox",
        checked: checked,
        onchange: () => this.toggle(id)
      }), this.attrs.section === 'categories' ? categorySymbol(tag) : tagSymbol(tag, '', 'fas fa-tag'), m("span", null, tag.name())));
    })), m("div", {
      className: "CanelaSidebarCustomize-actions"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.save()
    }, t('sidebar.customize_save')), m(Button, {
      className: "Button Button--link",
      onclick: () => this.reset()
    }, t('sidebar.customize_reset'))));
  }
  toggle(id) {
    if (this.selected.has(id)) this.selected.delete(id);else this.selected.add(id);
  }
  save() {
    setSidebarPicks(this.attrs.section, Array.from(this.selected));
    this.hide();
  }
  reset() {
    setSidebarPicks(this.attrs.section, null);
    this.hide();
  }
}
flarum.reg.add('ramon-canela', 'forum/components/SidebarCustomizeModal', SidebarCustomizeModal);